create table public.rubric_criteria(id uuid primary key default gen_random_uuid(),assignment_id uuid not null references public.assignments(id) on delete cascade,title text not null,description text not null default '',max_score numeric(7,2) not null check(max_score>0),display_order integer not null default 0,created_at timestamptz not null default now(),unique(assignment_id,display_order));
create table public.rubric_scores(submission_id uuid not null references public.assignment_submissions(id) on delete cascade,criterion_id uuid not null references public.rubric_criteria(id),score numeric(7,2) not null check(score>=0),feedback text not null default '',graded_by uuid not null references public.profiles(id),updated_at timestamptz not null default now(),primary key(submission_id,criterion_id));
create table public.learning_evidence(id uuid primary key default gen_random_uuid(),student_id uuid not null references public.profiles(id),objective_id uuid not null references public.learning_objectives(id),source_type text not null check(source_type in ('ASSIGNMENT','ASSESSMENT')),source_id uuid not null,score numeric(5,4) not null check(score between 0 and 1),created_at timestamptz not null default now(),unique(student_id,objective_id,source_type,source_id));
create table public.ai_generation_requests(id uuid primary key default gen_random_uuid(),teacher_id uuid not null references public.profiles(id),lesson_id uuid not null references public.lessons(id),quantity integer not null check(quantity between 1 and 50),parameters jsonb not null default '{}'::jsonb,status text not null default 'PROCESSING' check(status in ('PROCESSING','COMPLETED','FAILED')),error_message text,created_at timestamptz not null default now(),completed_at timestamptz);
create table public.ai_generation_outputs(id uuid primary key default gen_random_uuid(),request_id uuid not null references public.ai_generation_requests(id) on delete cascade,content text not null,kind text not null check(kind in ('SINGLE_CHOICE','MULTIPLE_CHOICE','TRUE_FALSE','SHORT_ANSWER','ESSAY')),objective_id uuid not null references public.learning_objectives(id),difficulty text not null default 'MEDIUM',bloom_level text,options jsonb not null default '[]'::jsonb,correct_answer jsonb,review_status text not null default 'PENDING_REVIEW' check(review_status in ('PENDING_REVIEW','APPROVED','REJECTED','EDITED_AND_APPROVED')),review_note text,reviewed_by uuid references public.profiles(id),reviewed_at timestamptz,approved_question_id uuid references public.questions(id));
create table public.content_revisions(id uuid primary key default gen_random_uuid(),class_id uuid not null references public.classes(id) on delete cascade,entity_type text not null,entity_id uuid not null,action text not null,actor_id uuid not null references public.profiles(id),before_state jsonb,after_state jsonb,created_at timestamptz not null default now());
create index content_revisions_class_created_idx on public.content_revisions(class_id,created_at desc);
alter table public.rubric_criteria enable row level security; alter table public.rubric_scores enable row level security; alter table public.learning_evidence enable row level security; alter table public.ai_generation_requests enable row level security; alter table public.ai_generation_outputs enable row level security; alter table public.content_revisions enable row level security;
create policy rubric_criteria_read on public.rubric_criteria for select to authenticated using(public.can_manage_assignment(assignment_id) or (public.can_access_course((select course_id from public.assignments where id=assignment_id)) and exists(select 1 from public.assignments a where a.id=assignment_id and a.status='PUBLISHED')));
create policy rubric_criteria_teacher_all on public.rubric_criteria for all to authenticated using(public.can_manage_assignment(assignment_id)) with check(public.can_manage_assignment(assignment_id));
create policy rubric_scores_read on public.rubric_scores for select to authenticated using(exists(select 1 from public.assignment_submissions s where s.id=submission_id and (public.can_manage_assignment(s.assignment_id) or (s.student_id=auth.uid() and s.graded_at is not null))));
create policy rubric_scores_teacher_all on public.rubric_scores for all to authenticated using(exists(select 1 from public.assignment_submissions s where s.id=submission_id and public.can_manage_assignment(s.assignment_id))) with check(exists(select 1 from public.assignment_submissions s where s.id=submission_id and public.can_manage_assignment(s.assignment_id) and graded_by=auth.uid()));
create policy evidence_read on public.learning_evidence for select to authenticated using(student_id=auth.uid() or exists(select 1 from public.learning_objectives o join public.lessons l on l.id=o.lesson_id join public.courses c on c.id=l.course_id join public.class_members m on m.class_id=c.class_id where o.id=objective_id and m.student_id=learning_evidence.student_id and public.can_manage_class(c.class_id)));
create policy ai_requests_teacher_all on public.ai_generation_requests for all to authenticated using(teacher_id=auth.uid() and public.current_app_role()='TEACHER' and exists(select 1 from public.lessons l where l.id=lesson_id and public.can_manage_course(l.course_id))) with check(teacher_id=auth.uid() and public.current_app_role()='TEACHER' and exists(select 1 from public.lessons l where l.id=lesson_id and public.can_manage_course(l.course_id)));
create policy ai_outputs_teacher_all on public.ai_generation_outputs for all to authenticated using(exists(select 1 from public.ai_generation_requests r join public.lessons l on l.id=r.lesson_id where r.id=request_id and r.teacher_id=auth.uid() and public.can_manage_course(l.course_id))) with check(exists(select 1 from public.ai_generation_requests r join public.lessons l on l.id=r.lesson_id where r.id=request_id and r.teacher_id=auth.uid() and public.can_manage_course(l.course_id) and reviewed_by is not distinct from auth.uid()));
create policy revisions_teacher_read on public.content_revisions for select to authenticated using(public.can_manage_class(class_id));
create policy revisions_teacher_insert on public.content_revisions for insert to authenticated with check(public.can_manage_class(class_id) and actor_id=auth.uid());
grant select,insert,update,delete on public.rubric_criteria,public.rubric_scores,public.ai_generation_requests,public.ai_generation_outputs,public.content_revisions to authenticated; grant select on public.learning_evidence to authenticated;
